% Batch convert supersonic DAQ .bin files into .mat files containing one
% struct, S, per file.
%
% This script takes .bin files generated by the supersonic DAQ program and
% converts each one into a .mat file containing:
%   - file metadatas
%   - acquisition metadata
%   - calibration metadata
%   - generated time vectors
%   - low-rate temperature data
%   - full raw decoded matrix
%   - calibrated/processed channel data
%
% Written by Erik Mueller, with help from ChatGPT.
%
% Output files are saved inside a generated folder called DAQ_data.

clear;
clc;

%% SETUP

% Option 1: manually enter the folder path
%inputFolder = 'C:\Users\oscar\Documents\UNSW\Thesis\BOS\Final testing 23-07\Diamonds';   % <-- CHANGE THIS

% Option 2: uncomment this line to manually select the folder
 inputFolder = uigetdir(pwd, 'Select folder containing .bin files');

if inputFolder == 0
    error('No folder selected.');
end

if ~isfolder(inputFolder)
    error('Input folder does not exist: %s', inputFolder);
end

outputFolder = fullfile(inputFolder, 'DAQ_data');

if ~isfolder(outputFolder)
    mkdir(outputFolder);
end

binFiles = dir(fullfile(inputFolder, '*.bin'));

if isempty(binFiles)
    error('No .bin files found in: %s', inputFolder);
end

%% CALIBRATION / CHANNEL SETTINGS

cfg = struct();

% Baratron sensitivity
cfg.Btron_sens_V_per_Pa = 72.51894557E-6;     % V/Pa

% Wika A-10 sensitivity is stored in the .bin metadata.
% Use manual override only if required.
cfg.UseManualWikaSensitivity = false;
cfg.ManualWika_sens_V_per_Pa = 5.003045194E-6;

% Surface Pressure tap sensitivity
cfg.Channel83_sens_kPa_per_V = 34.4737865;

% PCB 112A22 sensitivities
% Enter each PCB sensitivity individually in mV/kPa.
% Placeholder value is 14.91 mV/kPa until the correct values are entered.
cfg.PCB_sens_mV_per_kPa = struct( ...
    'ch90',  14.11, ...
    'ch91',  14.70, ...
    'ch92',  14.38, ...
    'ch93',  14.68, ...
    'ch100', 14.91, ...
    'ch101', 14.91, ...
    'ch102', 14.91, ...
    'ch103', 14.91);

% Channel classification
cfg.Baratron_Channel_IDs   = 80;                       % static pressure
cfg.Wika_Channel_IDs       = 81;                       % total pressure
cfg.WT_State_Channel_IDs   = 82;                       % unassigned wind tunnel state sensor
cfg.Channel83_Pressure_IDs = 83;                       % surface pressure sensor
cfg.PCB_Channel_IDs        = [90 91 92 93 100 101 102 103];
cfg.Unassigned_Channel_IDs = 110:113;

%% BATCH CONVERSION

fprintf('\nFound %d .bin files in:\n%s\n', numel(binFiles), inputFolder);
fprintf('Saving .mat files to:\n%s\n\n', outputFolder);

failedFiles = {};

for kk = 1:numel(binFiles)

    inputPath = fullfile(binFiles(kk).folder, binFiles(kk).name);

    [~, baseName, ~] = fileparts(binFiles(kk).name);
    outputPath = fullfile(outputFolder, [baseName, '.mat']);

    fprintf('(%d/%d) Converting %s ... ', kk, numel(binFiles), binFiles(kk).name);

    try
        S = convertDAQBinFile(inputPath, cfg);
        save(outputPath, 'S', '-v7.3');

        fprintf('done.\n');

    catch ME
        fprintf('FAILED.\n');
        warning('Could not convert %s:\n%s', binFiles(kk).name, ME.message);

        failedFiles(end+1,:) = {binFiles(kk).name, ME.message}; %#ok<SAGROW>
    end

end

%% SUMMARY

fprintf('\nBatch conversion complete.\n');
fprintf('Files found:     %d\n', numel(binFiles));
fprintf('Files converted: %d\n', numel(binFiles) - size(failedFiles,1));
fprintf('Files failed:    %d\n', size(failedFiles,1));

if ~isempty(failedFiles)
    fprintf('\nFailed files:\n');
    for ii = 1:size(failedFiles,1)
        fprintf('  %s\n    %s\n', failedFiles{ii,1}, failedFiles{ii,2});
    end
end

%% LOCAL FUNCTIONS

function S = convertDAQBinFile(inputPath, cfg)

    %% File names

    [inputFolder, baseName, ext] = fileparts(inputPath);
    sourceFilename = [baseName, ext];

    %% Determine number of channels

    fid = fopen(inputPath, 'r', 'ieee-le');

    if fid == -1
        error('Could not open file: %s', inputPath);
    end

    cleanupObj = onCleanup(@() fclose(fid));

    NoOfChannels = fread(fid, 1, 'double');

    if isempty(NoOfChannels) || NoOfChannels <= 0 || mod(NoOfChannels,1) ~= 0
        error('Invalid number of channels read from file.');
    end

    NoOfChannels = double(NoOfChannels);
    NoOfStoredColumns = NoOfChannels + 2;

    %% Read full data matrix

    frewind(fid);
    data = fread(fid, [NoOfStoredColumns Inf], 'double').';

    if isempty(data)
        error('No data read from file.');
    end

    if size(data, 2) ~= NoOfStoredColumns
        error('Stored data matrix does not have the expected number of columns.');
    end

    %% Metadata

    RunTime         = data(2,1);   % seconds
    Rate            = data(3,1);   % Hz
    Wika_sens_file  = data(4,1);   % V/Pa
    Time_Date_Stamp = data(5,1);   % encoded time/date stamp

    if cfg.UseManualWikaSensitivity
        Wika_sens_V_per_Pa = cfg.ManualWika_sens_V_per_Pa;
        WikaSensitivitySource = 'manual input';
    else
        Wika_sens_V_per_Pa = Wika_sens_file;
        WikaSensitivitySource = 'file metadata';
    end

    Channel_IDs = data(7:6+NoOfChannels, 1);

    NoOfSamples       = size(data, 1);
    Timestep          = 1 / Rate;
    CalculatedRunTime = NoOfSamples / Rate;

    if abs(CalculatedRunTime - RunTime) > Timestep
        warning('Calculated runtime %.6f s does not match stored runtime %.6f s.', ...
            CalculatedRunTime, RunTime);
    end

    %% Raw matrix column indices

    % Raw matrix layout:
    %
    % data(:,1)     = repeated metadata column
    % data(:,2)     = low-rate temperature data, zero padded
    % data(:,3:end) = high-rate DAQ channels

    metadataColumnIndex    = 1;
    temperatureColumnIndex = 2;
    firstDAQColumnIndex    = 3;
    daqColumnIndices       = firstDAQColumnIndex:(NoOfChannels + 2);

    if numel(daqColumnIndices) ~= NoOfChannels
        error('Number of DAQ column indices does not match NoOfChannels.');
    end

    %% Time vectors

    t_high_s = (0:NoOfSamples-1).' ./ Rate;

    %% Temperature

    % Temperature is stored in column 2 in degC, padded with zeros.
    % Remove zero padding and convert to Kelvin.

    Temperature_raw_C = data(:, temperatureColumnIndex);
    Temperature_raw_C(Temperature_raw_C == 0) = [];

    NoOfTempSamples = numel(Temperature_raw_C);
    Temperature_K   = Temperature_raw_C + 273.15;

    if NoOfTempSamples > 1
        t_temp_s = linspace(0, RunTime, NoOfTempSamples).';
    else
        t_temp_s = 0;
    end

    %% Channel struct

    Channels = makeChannelStruct(Channel_IDs, data, cfg, Wika_sens_V_per_Pa);

    %% Build output struct

    S = struct();

    %% File information

    fileInfo = dir(inputPath);

    S.file.sourceFilename     = sourceFilename;
    S.file.sourceName         = baseName;
    S.file.sourceFolder       = inputFolder;
    S.file.sourcePath         = inputPath;
    S.file.bytes              = fileInfo.bytes;
    S.file.conversionDateTime = char(datetime('now'));
    S.file.converterScript    = mfilename;

    %% Acquisition metadata

    S.acquisition.numberOfChannels      = NoOfChannels;
    S.acquisition.numberOfStoredColumns = NoOfStoredColumns;
    S.acquisition.numberOfSamples       = NoOfSamples;

    S.acquisition.runTime_s             = RunTime;
    S.acquisition.calculatedRunTime_s   = CalculatedRunTime;
    S.acquisition.sampleRate_Hz         = Rate;
    S.acquisition.timestep_s            = Timestep;

    S.acquisition.timeDateStamp_raw     = Time_Date_Stamp;
    S.acquisition.channelIDs            = Channel_IDs;

    %% Calibration metadata

    S.calibration.Baratron.sensitivity      = cfg.Btron_sens_V_per_Pa;
    S.calibration.Baratron.sensitivityUnits = 'V/Pa';

    S.calibration.WikaA10.sensitivity       = Wika_sens_V_per_Pa;
    S.calibration.WikaA10.fileSensitivity   = Wika_sens_file;
    S.calibration.WikaA10.sensitivityUnits  = 'V/Pa';
    S.calibration.WikaA10.sensitivitySource = WikaSensitivitySource;

    S.calibration.Channel83.sensitivity = cfg.Channel83_sens_kPa_per_V;
    S.calibration.Channel83.sensitivityUnits = 'kPa/V';

    S.calibration.PCB112A22.sensitivity      = cfg.PCB_sens_mV_per_kPa;
    S.calibration.PCB112A22.sensitivityUnits = 'mV/kPa';

    %% Time vectors

    S.time.highRate_s    = t_high_s;
    S.time.temperature_s = t_temp_s;
    S.time.units         = 's';

    %% Temperature data

    S.temperature.raw_C    = Temperature_raw_C;
    S.temperature.K        = Temperature_K;
    S.temperature.time_s   = t_temp_s;
    S.temperature.rawUnits = 'degC';
    S.temperature.units    = 'K';
    S.temperature.note     = ...
        'Temperature sampled at lower rate than pressure channels; zero padding removed.';

    %% Raw data preservation

    % Raw data are stored only once in the full decoded matrix.
    % Individual channels store raw column indices, not duplicate raw vectors.

    S.raw.fullMatrix = data;
    S.raw.precision  = 'double';
    S.raw.byteOrder  = 'ieee-le';

    S.raw.columnIndex.metadata    = metadataColumnIndex;
    S.raw.columnIndex.temperature = temperatureColumnIndex;
    S.raw.columnIndex.daqChannels = daqColumnIndices;

    S.raw.columnDescription.column1       = 'Repeated metadata column';
    S.raw.columnDescription.column2       = 'Low-rate temperature data, zero padded';
    S.raw.columnDescription.columns3toEnd = 'High-rate sampled DAQ channels';

    %% Channel data

    % Each entry in S.channels contains:
    %   id
    %   name
    %   description
    %   sensorType
    %   quantity
    %   rawColumn
    %   rawUnits
    %   processedValue
    %   processedUnits
    %   calibration
    %
    % Raw data are not duplicated inside each channel.
    % Retrieve raw values using:
    %
    %   raw = S.raw.fullMatrix(:, S.channels(ii).rawColumn);

    S.channels = Channels;

    %% Notes

    S.notes.unitConvention = ...
        'Pressure in kPa, temperature in K, time in seconds, unassigned channels retained as volts.';

    S.notes.channelConvention = ...
        'Channel IDs are read from metadata column. Known channels are calibrated; unknown channels are preserved as voltage.';

    S.notes.temperatureConvention = ...
        'Temperature was stored in degC in column 2 with zero padding and converted to K.';

    S.notes.rawDataPreserved = ...
        'The full raw matrix is preserved once in S.raw.fullMatrix. Raw channel vectors are not duplicated.';

end

function Channels = makeChannelStruct(Channel_IDs, data, cfg, Wika_sens_V_per_Pa)

    NoOfChannels = numel(Channel_IDs);
    Channels = repmat(emptyChannelStruct(), NoOfChannels, 1);

    for ii = 1:NoOfChannels

        chID      = Channel_IDs(ii);
        rawColumn = ii + 2;
        raw       = data(:, rawColumn);

        Channels(ii).id        = chID;
        Channels(ii).rawColumn = rawColumn;
        Channels(ii).rawUnits  = 'V';

        if ismember(chID, cfg.Baratron_Channel_IDs)

            Channels(ii) = definePressureChannel( ...
                Channels(ii), ...
                sprintf('ch%.0f_Baratron_static_pressure', chID), ...
                'Baratron static pressure reading', ...
                'Baratron', ...
                'static pressure', ...
                cfg.Btron_sens_V_per_Pa, ...
                'V/Pa');

            Channels(ii).processedValue = raw ./ cfg.Btron_sens_V_per_Pa ./ 1000;
            Channels(ii).processedUnits = 'kPa';

        elseif ismember(chID, cfg.Wika_Channel_IDs)

            Channels(ii) = definePressureChannel( ...
                Channels(ii), ...
                sprintf('ch%.0f_Wika_total_pressure', chID), ...
                'Wika A-10 total pressure reading', ...
                'Wika A-10', ...
                'total pressure', ...
                Wika_sens_V_per_Pa, ...
                'V/Pa');

            Channels(ii).processedValue = raw ./ Wika_sens_V_per_Pa ./ 1000;
            Channels(ii).processedUnits = 'kPa';

        elseif ismember(chID, cfg.PCB_Channel_IDs)

            sensField = sprintf('ch%.0f', chID);

            if isfield(cfg.PCB_sens_mV_per_kPa, sensField)
                sens = cfg.PCB_sens_mV_per_kPa.(sensField);
            else
                warning('No PCB sensitivity entered for channel %.0f. Using 14.91 mV/kPa.', chID);
                sens = 14.91;
            end

            Channels(ii) = definePressureChannel( ...
                Channels(ii), ...
                sprintf('ch%.0f_PCB_pressure', chID), ...
                'PCB Piezotronics 112A22 pressure transducer', ...
                'PCB 112A22', ...
                'pressure fluctuation', ...
                sens, ...
                'mV/kPa');

            Channels(ii).processedValue = raw .* 1000 ./ sens;
            Channels(ii).processedUnits = 'kPa';

        elseif ismember(chID, cfg.Channel83_Pressure_IDs)

            Channels(ii) = definePressureChannel( ...
                Channels(ii), ...
                sprintf('ch%.0f_pressure', chID), ...
                'Standard 0-10 V / 0-50 psi pressure sensor', ...
                'Pressure sensor', ...
                'pressure', ...
                cfg.Channel83_sens_kPa_per_V, ...
                'kPa/V');
        
            Channels(ii).processedValue = ...
                raw .* cfg.Channel83_sens_kPa_per_V;
        
            Channels(ii).processedUnits = 'kPa';
                elseif ismember(chID, cfg.WT_State_Channel_IDs)

            Channels(ii) = defineVoltageChannel( ...
                Channels(ii), ...
                sprintf('ch%.0f_wind_tunnel_state_sensor', chID), ...
                'Unassigned wind tunnel state sensor', ...
                'unassigned', ...
                'wind tunnel state');

            Channels(ii).processedValue = raw;
            Channels(ii).processedUnits = 'V';

        elseif ismember(chID, cfg.Unassigned_Channel_IDs)

            Channels(ii) = defineVoltageChannel( ...
                Channels(ii), ...
                sprintf('ch%.0f_unassigned_voltage', chID), ...
                'Unassigned voltage channel', ...
                'unassigned', ...
                'voltage');

            Channels(ii).processedValue = raw;
            Channels(ii).processedUnits = 'V';

        else

            Channels(ii) = defineVoltageChannel( ...
                Channels(ii), ...
                sprintf('ch%.0f_other_voltage', chID), ...
                'Other channel, retained as voltage', ...
                'other', ...
                'voltage');

            Channels(ii).processedValue = raw;
            Channels(ii).processedUnits = 'V';

        end

    end

end

function ch = emptyChannelStruct()

    ch = struct( ...
        'id', [], ...
        'name', '', ...
        'rawColumn', [], ...
        'rawUnits', 'V', ...
        'description', '', ...
        'sensorType', '', ...
        'quantity', '', ...
        'calibration', struct(), ...
        'processedValue', [], ...
        'processedUnits', '');

end

function ch = definePressureChannel(ch, name, description, sensorType, quantity, sensitivity, sensitivityUnits)

    ch.name        = name;
    ch.description = description;
    ch.sensorType  = sensorType;
    ch.quantity    = quantity;

    ch.calibration.sensitivity = sensitivity;
    ch.calibration.units       = sensitivityUnits;

end

function ch = defineVoltageChannel(ch, name, description, sensorType, quantity)

    ch.name        = name;
    ch.description = description;
    ch.sensorType  = sensorType;
    ch.quantity    = quantity;

    ch.processedValue = [];
    ch.processedUnits = 'V';

end